const max = 998;
const prime = Array(max + 1).fill(true);
prime[0] = prime[1] = false;
for (let p = 2; p * p <= max; p++) {
  if (prime[p]) {
    for (let n = p * p; n <= max; n += p) prime[n] = false;
  }
}
let checked = 0;
const counterexamples = [];
for (let n = 4; n <= max; n += 2) {
  checked++;
  let found = false;
  for (let p = 2; p <= n / 2; p++) {
    if (prime[p] && prime[n - p]) {
      found = true;
      break;
    }
  }
  if (!found) counterexamples.push(n);
}
console.log(JSON.stringify({ checked, counterexamples }));

